// ── Extract binary file and prepare base64 for AksonOCR ──────────────
const item = $input.first();
const binary = item.binary;

if (!binary) {
  throw new Error('ไม่พบไฟล์ในคำขอ');
}

// Find the file field (could be 'slip', 'file', or 'data')
const fileKey = Object.keys(binary)[0];
if (!fileKey) {
  throw new Error('ไม่พบ binary data');
}

const fileData = binary[fileKey];
const base64 = fileData.data;         // already base64 in n8n
const mimeType = fileData.mimeType || 'image/jpeg';
const fileName = fileData.fileName || 'slip.jpg';

// Prepare document payload for AksonOCR v2
let document;
if (mimeType === 'application/pdf') {
  document = {
    type: 'document_url',
    document_url: `data:application/pdf;base64,${base64}`,
    document_name: fileName
  };
} else {
  document = {
    type: 'document_url',
    document_url: `data:${mimeType};base64,${base64}`
  };
}

return [{
  json: {
    // Form fields from web app
    type: item.json.body?.type || item.json.type || 'expense',
    category: item.json.body?.category || item.json.category || 'อื่นๆ',
    note: item.json.body?.note || item.json.note || '',
    fileName: item.json.body?.fileName || fileName,
    uploadedAt: item.json.body?.uploadedAt || new Date().toISOString(),
    // AksonOCR payload
    ocrPayload: {
      model: 'AksonOCR-1.0',
      document: document
    }
  }
}];

// ── Parse OCR text → Extract structured financial data ────────────────
const item = $input.first();

// AksonOCR v2 returns: { pages: [{ markdown: '...' }], ... }
const ocrResult = item.json;
const rawText = ocrResult?.pages?.[0]?.markdown
  || ocrResult?.text
  || ocrResult?.content
  || JSON.stringify(ocrResult);

// Metadata from previous step
const meta = $('Prepare File for OCR').first().json;

// ── Helper functions ────────────────────────────────────────────────
function extractAmount(text) {
  const patterns = [
    /ยอดเงิน\s*:?\s*([\d,]+\.?\d*)\s*บาท/i,
    /จำนวน\s*:?\s*([\d,]+\.?\d*)\s*บาท/i,
    /ยอดโอน\s*:?\s*([\d,]+\.?\d*)\s*บาท/i,
    /รวมทั้งหมด\s*:?\s*([\d,]+\.?\d*)/i,
    /Total\s*:?\s*([\d,]+\.?\d*)/i,
    /amount\s*:?\s*([\d,]+\.?\d*)/i,
    /([\d,]+\.\d{2})\s*(?:บาท|THB|฿)/i,
    /฿\s*([\d,]+\.?\d*)/i,
  ];
  for (const p of patterns) {
    const m = text.match(p);
    if (m) return parseFloat(m[1].replace(/,/g, ''));
  }
  return null;
}

function extractDate(text) {
  const patterns = [
    /วันที่\s*:?\s*(\d{1,2})[\/-\.](\d{1,2})[\/-\.](\d{2,4})/,
    /date\s*:?\s*(\d{1,2})[\/-\.](\d{1,2})[\/-\.](\d{2,4})/i,
    /(\d{1,2})[\/-\.](\d{1,2})[\/-\.](\d{2,4})/,
  ];
  for (const p of patterns) {
    const m = text.match(p);
    if (m) {
      let y = parseInt(m[3]);
      if (y > 2400) y -= 543; // Buddhist → CE
      if (y < 100) y += 2000;
      return `${m[1].padStart(2,'0')}/${m[2].padStart(2,'0')}/${y}`;
    }
  }
  return new Date().toLocaleDateString('th-TH', {day:'2-digit',month:'2-digit',year:'numeric'});
}

function extractTime(text) {
  const m = text.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) return `${m[1].padStart(2,'0')}:${m[2]}:${(m[3]||'00')}`;
  return new Date().toLocaleTimeString('th-TH', {hour:'2-digit',minute:'2-digit',second:'2-digit'});
}

function extractBank(text) {
  const banks = [
    ['กสิกรไทย', 'ธ.กสิกรไทย (KBANK)'],
    ['kbank', 'ธ.กสิกรไทย (KBANK)'],
    ['ไทยพาณิชย์', 'ธ.ไทยพาณิชย์ (SCB)'],
    ['\bscb\b', 'ธ.ไทยพาณิชย์ (SCB)'],
    ['กรุงเทพ', 'ธ.กรุงเทพ (BBL)'],
    ['\bbbl\b', 'ธ.กรุงเทพ (BBL)'],
    ['กรุงไทย', 'ธ.กรุงไทย (KTB)'],
    ['\bktb\b', 'ธ.กรุงไทย (KTB)'],
    ['กรุงศรี', 'ธ.กรุงศรี (BAY)'],
    ['\bbay\b', 'ธ.กรุงศรี (BAY)'],
    ['ทหารไทย', 'ธ.ทหารไทย (TTB)'],
    ['\bttb\b', 'ธ.ทหารไทย (TTB)'],
    ['ออมสิน', 'ธ.ออมสิน (GSB)'],
    ['\bgsb\b', 'ธ.ออมสิน (GSB)'],
    ['อาคารสงเคราะห์', 'ธ.อาคารสงเคราะห์ (GHB)'],
    ['\bghb\b', 'ธ.อาคารสงเคราะห์ (GHB)'],
    ['ยูโอบี', 'ธ.ยูโอบี (UOB)'],
    ['\buob\b', 'ธ.ยูโอบี (UOB)'],
    ['ซีไอเอ็มบี', 'ธ.ซีไอเอ็มบี (CIMB)'],
    ['\bcimb\b', 'ธ.ซีไอเอ็มบี (CIMB)'],
    ['ทิสโก้', 'ธ.ทิสโก้ (TISCO)'],
    ['promtpay', 'พร้อมเพย์ (PromptPay)'],
    ['promptpay', 'พร้อมเพย์ (PromptPay)'],
    ['พร้อมเพย์', 'พร้อมเพย์ (PromptPay)'],
    ['truemoney', 'TrueMoney Wallet'],
    ['ทรูมันนี่', 'TrueMoney Wallet'],
    ['shopee', 'ShopeePay'],
    ['grabpay', 'GrabPay'],
  ];
  const lower = text.toLowerCase();
  const found = [];
  for (const [key, name] of banks) {
    if (new RegExp(key, 'i').test(lower) && !found.includes(name)) {
      found.push(name);
      if (found.length === 2) break;
    }
  }
  return found;
}

function extractReference(text) {
  const patterns = [
    /(?:เลขที่อ้างอิง|ref(?:erence)?(?:\s*no\.?)?|รหัสอ้างอิง|transaction\s*(?:id|no))\s*:?\s*([A-Za-z0-9]{6,})/i,
    /(?:ref|ref\.\s*no)\s*:?\s*([A-Za-z0-9]{6,})/i,
  ];
  for (const p of patterns) {
    const m = text.match(p);
    if (m) return m[1];
  }
  return '';
}

function extractMerchant(text) {
  const patterns = [
    /(?:ร้าน|บริษัท|หจก\.|บจก\.)\s*([^\n]{2,50})/i,
    /(?:ผู้รับ|receiver|beneficiary|to)\s*:?\s*([^\n]{2,50})/i,
    /(?:ชื่อผู้รับ)\s*:?\s*([^\n]{2,50})/i,
  ];
  for (const p of patterns) {
    const m = text.match(p);
    if (m) return m[1].trim().replace(/[|\\]/g, '').trim();
  }
  return '';
}

function extractAccountNumber(text) {
  const m = text.match(/(\d{3}[-\s]?\d{1,4}[-\s]?\d{4,5}(?:[-\s]?\d)?)/);
  return m ? m[1].replace(/\s/g, '') : '';
}

// ── Extract all fields ──────────────────────────────────────────────
const amount = extractAmount(rawText);
const date = extractDate(rawText);
const time = extractTime(rawText);
const banks = extractBank(rawText);
const bankSender = banks[0] || '';
const bankReceiver = banks[1] || banks[0] || '';
const reference = extractReference(rawText);
const merchant = extractMerchant(rawText);
const accountNumber = extractAccountNumber(rawText);

const rowId = `SV-${Date.now()}`;
const status = amount ? 'processed' : 'manual_review';

return [{
  json: {
    id: rowId,
    uploadedAt: meta.uploadedAt,
    transactionDate: date,
    transactionTime: time,
    amount: amount || 0,
    type: meta.type,
    category: meta.category,
    merchant: merchant,
    bankSender: bankSender,
    bankReceiver: bankReceiver,
    accountNumber: accountNumber,
    reference: reference,
    note: meta.note,
    ocrText: rawText.substring(0, 1000), // cap at 1000 chars
    fileName: meta.fileName,
    status: status
  }
}];

// ── Filter and format transactions ────────────────────────────────────
const items = $input.all();
const query = $('Webhook - Get Transactions').first().json.query || {};

const { month, year, type, category, limit = 500 } = query;

let rows = items.map(i => ({
  id: i.json['ID'] || '',
  uploadedAt: i.json['Uploaded At'] || '',
  transactionDate: i.json['Transaction Date'] || '',
  transactionTime: i.json['Transaction Time'] || '',
  amount: parseFloat(i.json['Amount']) || 0,
  type: (i.json['Type'] || 'expense').toLowerCase(),
  category: i.json['Category'] || 'อื่นๆ',
  merchant: i.json['Merchant / Payee'] || '',
  bankSender: i.json['Bank Sender'] || '',
  bankReceiver: i.json['Bank Receiver'] || '',
  accountNumber: i.json['Account Number'] || '',
  reference: i.json['Reference No'] || '',
  note: i.json['Note'] || '',
  fileName: i.json['File Name'] || '',
  status: i.json['Status'] || 'processed',
})).filter(r => r.id); // skip empty rows

// Filter by month/year from transactionDate (DD/MM/YYYY)
if (month || year) {
  rows = rows.filter(r => {
    const parts = r.transactionDate.split('/');
    if (parts.length < 3) return true;
    const rowMonth = parseInt(parts[1]);
    const rowYear = parseInt(parts[2]) > 2400 ? parseInt(parts[2]) - 543 : parseInt(parts[2]);
    if (month && rowMonth !== parseInt(month)) return false;
    if (year && rowYear !== parseInt(year)) return false;
    return true;
  });
}

if (type) rows = rows.filter(r => r.type === type);
if (category) rows = rows.filter(r => r.category === category);

// Sort newest first
rows.sort((a, b) => {
  const dateA = a.uploadedAt || a.transactionDate;
  const dateB = b.uploadedAt || b.transactionDate;
  return new Date(dateB) - new Date(dateA);
});

rows = rows.slice(0, parseInt(limit));

return [{ json: { transactions: rows, total: rows.length } }];

// ── Calculate summary statistics ──────────────────────────────────────
const items = $input.all();
const query = $('Webhook - Get Summary').first().json.query || {};
const { month, year } = query;

let rows = items.map(i => ({
  type: (i.json['Type'] || 'expense').toLowerCase(),
  amount: parseFloat(i.json['Amount']) || 0,
  category: i.json['Category'] || 'อื่นๆ',
  transactionDate: i.json['Transaction Date'] || '',
  id: i.json['ID'] || '',
})).filter(r => r.id);

// Filter by period
if (month || year) {
  rows = rows.filter(r => {
    const parts = r.transactionDate.split('/');
    if (parts.length < 3) return true;
    const rowMonth = parseInt(parts[1]);
    const rowYear = parseInt(parts[2]) > 2400 ? parseInt(parts[2]) - 543 : parseInt(parts[2]);
    if (month && rowMonth !== parseInt(month)) return false;
    if (year && rowYear !== parseInt(year)) return false;
    return true;
  });
}

const incomeRows = rows.filter(r => r.type === 'income');
const expenseRows = rows.filter(r => r.type === 'expense');

const totalIncome = incomeRows.reduce((s, r) => s + r.amount, 0);
const totalExpense = expenseRows.reduce((s, r) => s + r.amount, 0);

// By category
const byCat = {};
for (const r of expenseRows) {
  byCat[r.category] = (byCat[r.category] || 0) + r.amount;
}

// By month (last 12)
const byMonth = {};
for (const r of rows) {
  const parts = r.transactionDate.split('/');
  if (parts.length < 3) continue;
  const m = parseInt(parts[1]);
  let y = parseInt(parts[2]);
  if (y > 2400) y -= 543;
  const key = `${y}-${m.toString().padStart(2,'0')}`;
  if (!byMonth[key]) byMonth[key] = { income: 0, expense: 0 };
  if (r.type === 'income') byMonth[key].income += r.amount;
  else if (r.type === 'expense') byMonth[key].expense += r.amount;
}

return [{
  json: {
    totalIncome: Math.round(totalIncome * 100) / 100,
    totalExpense: Math.round(totalExpense * 100) / 100,
    balance: Math.round((totalIncome - totalExpense) * 100) / 100,
    totalCount: rows.length,
    incomeCount: incomeRows.length,
    expenseCount: expenseRows.length,
    byCategory: Object.entries(byCat)
      .sort((a,b) => b[1]-a[1])
      .map(([cat, amount]) => ({ category: cat, amount: Math.round(amount*100)/100 })),
    byMonth: Object.entries(byMonth)
      .sort((a,b) => a[0].localeCompare(b[0]))
      .slice(-12)
      .map(([month, v]) => ({ month, ...v }))
  }
}];
